use {
    crate::domain::eth,
    ethrpc::current_block::CurrentBlockStream,
    reqwest::ClientBuilder,
    std::time::Duration,
    thiserror::Error,
};

mod dto;

const GAS_LIMIT: u64 = 30_000_000;

#[derive(Debug, Clone)]
pub(super) struct Enso {
    url: reqwest::Url,
    chain_id: eth::ChainId,
    current_block: CurrentBlockStream,
    network_block_interval: Option<Duration>,
}

#[derive(Debug, Clone)]
pub struct Config {
    /// The URL of the Transaction Simulator API.
    pub url: reqwest::Url,
    /// The network block interval, used to estimate the timestamp of the
    /// pending block so transactions can be simulated against it. If unset,
    /// transactions are simulated against the latest block.
    pub network_block_interval: Option<Duration>,
}

impl Enso {
    pub(super) fn new(
        config: Config,
        chain_id: eth::ChainId,
        current_block: CurrentBlockStream,
    ) -> Self {
        Self {
            url: reqwest::Url::parse(&format!("{}api/v1/simulate", config.url)).unwrap(),
            chain_id,
            current_block,
            network_block_interval: config.network_block_interval,
        }
    }

    pub(super) async fn simulate(&self, tx: eth::Tx) -> Result<eth::Gas, Error> {
        // Obtain the current block number and, if configured, the estimated
        // timestamp of the pending block. Simulations on the latest block can
        // produce false negatives for transactions that would succeed on the
        // pending block, so we approximate the pending block by using its
        // expected timestamp.
        let block_number = self.current_block.borrow().number;
        let block_timestamp = self.network_block_interval.map(|interval| {
            self.current_block.borrow().timestamp + interval.as_secs()
        });

        let res: dto::Response = ClientBuilder::new()
            .build()
            .unwrap()
            .post(self.url.clone())
            .json(&dto::Request {
                chain_id: self.chain_id.into(),
                from: tx.from.into(),
                to: tx.to.into(),
                data: tx.input.into(),
                value: tx.value.into(),
                gas_limit: GAS_LIMIT,
                block_number: Some(block_number),
                block_timestamp,
                access_list: if tx.access_list.is_empty() {
                    None
                } else {
                    Some(tx.access_list.into())
                },
            })
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;

        res.into()
    }
}

