const http = require("http");
const fs = require("fs");
const path = require("path");

const [url, dest] = process.argv.slice(2);
const out = fs.createWriteStream(dest);

function attempt(n) {
  const req = http.get(url, { timeout: 90000 }, (res) => {
    if (res.statusCode !== 200) {
      res.resume();
      console.error(`status ${res.statusCode} (attempt ${n})`);
      out.close(() => fs.unlinkSync(dest));
      if (n < 15) setTimeout(() => attempt(n + 1), 2000);
      else process.exit(1);
      return;
    }
    res.pipe(out);
    out.on("finish", () => {
      console.log("downloaded");
      process.exit(0);
    });
  });
  req.on("timeout", () => req.destroy());
  req.on("error", (err) => {
    console.error(`err ${err.message} (attempt ${n})`);
    out.close(() => fs.unlinkSync(dest));
    if (n < 15) setTimeout(() => attempt(n + 1), 2000);
    else process.exit(1);
  });
}

attempt(1);

