    out.destroy();
    if (fs.existsSync(dest)) fs.unlinkSync(dest);
    if (n < 40) setTimeout(() => attempt(n + 1, 0), 1500);
    else process.exit(1);
  }
  const req = http.get(url, { timeout: 120000 }, (res) => {
    if (res.statusCode !== 200) {
