      process.exit(0);
    });
    req.on("timeout", () => {
      console.error(`attempt ${n} timeout after ${bytes} bytes`);
      req.destroy();
      cleanup();
    });
  });
  req.on("error", (err) => {
    console.error(`attempt ${n} err ${err.message}`);
    cleanup();
  });
}

