function attempt(n) {
  if (fs.existsSync(dest)) fs.unlinkSync(dest);
  const out = fs.createWriteStream(dest);
  const req = http.get(
    url,
    {
      timeout: 120000,
      headers: {
        "User-Agent": "npm/9.8.1 node/v20.20.2 linux x64",
        Accept: "*/*",
        "Accept-Encoding": "identity",
      },
    },
    (res) => {
      if (res.statusCode !== 200) {
        res.resume();
        out.destroy();
        fs.unlinkSync(dest);
        console.error(`atts[] status ${res.statusCode}`);
        return retry(n);
      }
      let bytes = 0;
      res.on("data", (c) => (bytes += c.length));
      res.pipe(out);
      out.on("finish", () => {
        console.error("downloaded " + fs.statSync(dest).size + " bytes");
        process.exit(0);
      });
      req.on("timeout", () => {
        console.error(`atts[] timeout after ${bytes}B`);
        req.destroy();
        return retry(n);
      });
    },
  );
  req.on("error", (err) => {
    console.error(`attempt ${n} err ${err.message}`);
    retry(n);
  });
}

function retry(n) {
  if (fs.existsSync(dest)) fs.unlinkSync(dest);
  if (n < 60) setTimeout(() => attempt(n + 1), 1500);
  else process.exit(1);
