    // compare (zero gas would make comparison meaningless).
    let mut valid_estimates = results
        .iter()
        .filter_map(|(index, result)| match result {
            Ok(estimate) if estimate.gas > 0 => Some((*index, estimate)),
            Ok(_) | Err(_) => None,
        })
        .collect::<Vec<_>>();

