fn pick_best_quote_result(
    results: &[(EstimatorIndex, PriceEstimateResult)],
    context: &RankingContext,
    query: &Query,
) -> Result<usize, PriceEstimationError> {
    // Best estimate, taking into account outliers in gas cost. Estimates that
    // report an error or a gas cost of `0` cannot be trusted because a
    // transaction always has a non-zero gas cost, so a solver could report
    // `0` to win the competition and subsidize the order fees with protocol艜
    // funds.
    let mut best_estimate = results
        .iter()
        .enumerate()
        .filter_map(|(index, (_, result))| {
            let estimate = result.as_ref().ok()?;
            (estimate.gas > 0).then_some((index, *estimate))
        })
        .collect::<Vec<_>>();

    // The median gas cost across all estimates and its lower bound (50% of the
    // median). Estimates that report a gas cost below this bound are discarded
    // as outliers that report a suspiciously low gas cost to win the
    // competition.
    let mut gas_values = best_estimate
        .iter()
        .map(|(_, estimate)| estimate.gas)
        .collect::<Vec<_>>();
    gas_values.sort_unstable();
    if let Some(&median) = gas_values.get(gas_values.len() / 2) {
        best_estimate.retain(|(_, estimate)| estimate.gas >= median / 2);
        let (_, (best_index, _)) = best_estimate
            .iter()
            .enumerate()
            .max_by(|(_, (_, a)), (_, (_, b))| {
                compare_quote_result(query, &Ok(*a), &Ok(*b), context)
            })
            .unwrap();
        return Ok(*best_index);
    }

    // No estimate with a meaningful gas cost is available. If some estimators
    // did return an estimate (but all reported a gas cost of `0`) there is
    // nothing to compare, so an internal error is returned. Otherwise all
    // estimators returned an error, in which case the error with the highest
    // priority is returned so that its result can be cached.
    if results.iter().any(|(_, result)| result.is_ok()) {
        Err(PriceEstimationError::EstimatorInternal(anyhow!(
            "not a single estimate with a non-zero gas cost"
        )))
    } else {
        let (best_index, _) = results
            .iter()
            .enumerate()
            .max_by(|(_, a), (_, b)| compare_quote_result(query, a, b, context))
            .unwrap();
        Ok(best_index)
    }
}

fn pick_best_native_result(
    results: &[(EstimatorIndex, NativePriceEstimateResult)],
) -> Result<usize, PriceEstimationError> {
    let best_index = results
        .iter()
        .enumerate()
        .max_by(|(_, a), (_, b)| compare_native_result(a, b))
        .map(|(index, _)| index)
        .unwrap();
    Ok(best_index)
}

fn compare_quote_result(
    query: &Query,
    a: &PriceEstimateResult,
    b: &PriceEstimateResult,
    context: &RankingContext,
) -> Ordering {
    match (a, b) {
        (Ok(a), Ok(b)) => compare_estimate_out_amount(query, a, b, context),
        (Ok(_), Err(_)) => Ordering::Greater,
        (Err(_), Ok(_)) => Ordering::Less,
        (Err(a), Err(b)) => compare_errors(a, b),
    }
}

fn compare_native_result(
    a: &NativePriceEstimateResult,
    b: &NativePriceEstimateResult,
) -> Ordering {
    match (a, b) {
        (Ok(a), Ok(b)) => a.partial_cmp(b).unwrap_or(Ordering::Equal),
        (Ok(_), Err(_)) => Ordering::Greater,
        (Err(_), Ok(_)) => Ordering::Less,
        (Err(a), Err(b)) => compare_errors(a, b),
    }
}

fn compare_estimate_out_amount(
    query: &Query,
    a: &Estimate,
    b: &Estimate,
    context: &RankingContext,
) -> Ordering {
    let a = context.effective_eth_out(a, query.kind);
    let b = context.effective_eth_out(b, query.kind);
    match query.kind {
        OrderKind::Buy => b.cmp(&a),
        OrderKind::Sell => a.cmp(&b),
    }
}

fn compare_errors(a: &PriceEstimationError, b: &PriceEstimationError) -> Ordering {
    // Errors are sorted by recoverability. E.g. a rate-limited estimation may
    // succeed if tried again, whereas unsupported order types can never recover
    // unless code changes. This can be used to decide which errors we want to
    // cache.
    fn error_to_integer_priority(err: &PriceEstimationError) -> u8 {
        match err {
            // highest priority (prefer)
            PriceEstimationError::RateLimited => 5,
            PriceEstimationError::ProtocolInternal(_) => 4,
            PriceEstimationError::EstimatorInternal(_) => 3,
            PriceEstimationError::UnsupportedToken { .. } => 2,
            PriceEstimationError::NoLiquidity => 1,
            PriceEstimationError::UnsupportedOrderType(_) => 0,
            // lowest priority
        }
    }
    error_to_integer_priority(b).cmp(&error_to_integer_priority(a))
}

