    /// Calculate the protocol fee for the given clearing prices and create a
    /// new fulfillment which pays that fee.
    pub fn with_protocol_fee(
        &self,
        prices: ClearingPrices,
    ) -> Result<Trade, Error> {
        // protocol fee is only applied to orders which have a dynamic fee (i.e. limit orders)
        let order = &self.order;
        let protocol_fee = match order.fee_policies.len() {
            0 => order::SellAmount::default(),
