/// Price improvement achieved for the order.
fn surplus_buy_amount(
    order: &order::Order,
    executed: order::TargetAmount,
    prices: ClearingPrices,
) -> Result<eth::TokenAmount, Error> {
    let buy_amount = buy_amount(order, executed, prices)?;
    let sell_amount = sell_amount(order, executed, prices)?;
    let limit_buy_amount = order.buy.amount;
    let limit_sell_amount = order.sell.amount;

    match order.side {
        order::Side::Buy => {
            // Buy order: the improvement is the difference between the limit sell and executed sell
            let sell_amount = sell_amount.0;
            let limit_sell_amount = limit_sell_amount.0;
            if sell_amount > limit_sell_amount {
                return Err(Error::InvalidExecution);
            }
            Ok(eth::TokenAmount(
                limit_sell_amount - sell_amount
            ))
        }
        order::Side::Sell => {
            // Sell order: the improvement is the difference between the executed buy and limit buy
            let buy_amount = buy_amount.0;
            let limit_buy_amount = limit_buy_amount.0;
            if buy_amount < limit_buy_amount {
                return Err(Error::InvalidExecution);
            }
            Ok(eth::TokenAmount(buy_amount - limit_buy_amount))
        }
    }
}

