#[derive(Debug, Error)]
pub enum Error {
    #[error("protocol fee applied to an order with a static fee")]
    ProtocolFeeOnStaticOrder,
    #[error("overflow error while calculating protocol fee")]
    Overflow,
    #[error("orders with more than one fee policy are not supported")]
    MultipleFeePolicies,
}

/// The uniform clearing prices of the two tokens of an order, used to
/// calculate the protocol fee for its fulfillment.
#[derive(Debug, Clone, Copy)]
pub struct ClearingPrices {
    /// The clearing price for the order's sell token.
    pub sell: eth::U256,
    /// The clearing price for the order's buy token.
    pub buy: eth::U256,
}

impl Fulfillment {
    /// Adjusts the fulfillment to include the protocol fee calculated from the
    /// order's fee policies and the given uniform clearing prices.
    ///
    /// The protocol fee is collected by reducing the executed amount of sell
    /// orders and increasing the fee amount, thereby pocketing the fee from
    /// the user's surplus.
    pub fn with_protocol_fee(&self, prices: ClearingPrices) -> Result<Trade, Error> {
        let order = &self.order;

        let protocol_fee = self.protocol_fee(prices)?;

        // If the protocol fee is zero, the fulfillment doesn't need to be
        // modified. This is the case for orders without fee policies, e.g.
        // market and liquidity orders.
        if protocol_fee.is_zero() {
            return Ok(Trade::Fulfillment(self.to_owned()));
        }

        let new_executed = match order.side {
            // The executed amount of a sell order is denominated in the sell
            // token, so the protocol fee is deducted from it.
            order::Side::Sell => self
                .executed
                .0
                .checked_sub(protocol_fee)
                .ok_or(Error::Overflow)?,
            // The executed amount of a buy order is denominated in the buy
            // token and remains unchanged.
            order::Side::Buy => self.executed.0,
        };

        match &self.fee {
            Fee::Dynamic(fee) => {
                let new_fee = fee.0.checked_add(protocol_fee).ok_or(Error::Overflow)?;
                Ok(Trade::Fulfillment(Self {
                    order: order.clone(),
                    executed: order::TargetAmount(new_executed),
                    fee: Fee::Dynamic(order::SellAmount(new_fee)),
                }))
            }
            Fee::Static => Err(Error::ProtocolFeeOnStaticOrder),
        }
    }

    /// Calculates the protocol fee for this fulfillment based on the order's
    /// fee policies. The fee is expressed in the order's sell token.
    fn protocol_fee(&self, prices: ClearingPrices) -> Result<eth::U256, Error> {
        let order = &self.order;
        let fee = match order.fee_policies.len() {
            0 => eth::U256::zero(),
            1 => match order.fee_policies[0] {
                FeePolicy::PriceImprovement {
                    factor,
                    max_volume_factor,
                } => {
                    let by_improvement = self.price_improvement_fee(prices, factor)?;
                    let by_volume = self.volume_fee(prices, max_volume_factor)?;
                    // Cap the price improvement fee with a percentage of the
                    // order's volume.
                    by_improvement.min(by_volume)
                }
                FeePolicy::Volume { factor } => self.volume_fee(prices, factor)?,
            },
            _ => return Err(Error::MultipleFeePolicies),
        };
        Ok(fee)
    }

    /// Calculates the price improvement fee for this fulfillment. The fee is
    /// expressed in the order's sell token.
    fn price_improvement_fee(
        &self,
        prices: ClearingPrices,
        factor: f64,
    ) -> Result<eth::U256, Error> {
        let order = &self.order;
        let surplus = surplus_buy_amount(order, self.executed, prices)?;
        let fee = eth::U256::from_f64_lossy(eth::U256::to_f64_lossy(surplus) * factor);
        let fee = match order.side {
            // The surplus of a sell order is denominated in the buy token, so
            // the fee is converted into the sell token.
            order::Side::Sell => sell_amount(fee, prices)?,
            // The surplus of a buy order is denominated in the sell token.
            order::Side::Buy => fee,
        };
        Ok(fee)
    }

    /// Calculates the volume fee for this fulfillment. The fee is expressed in
    /// the order's sell token.
    fn volume_fee(&self, prices: ClearingPrices, factor: f64) -> Result<eth::U256, Error> {
        let order = &self.order;
        let fee = match order.side {
            // The executed amount of a sell order is denominated in the sell
            // token.
            order::Side::Sell => {
                eth::U256::from_f64_lossy(eth::U256::to_f64_lossy(self.executed.0) * factor)
            }
            // The executed amount of a buy order is denominated in the buy
            // token, so the fee is converted into the sell token.
            order::Side::Buy => {
                let fee =
                    eth::U256::from_f64_lossy(eth::U256::to_f64_lossy(self.executed.0) * factor);
                sell_amount(fee, prices)?
            }
        };
        Ok(fee)
    }
}

/// The amount of sell tokens needed to buy the given amount of buy tokens at
/// the given clearing prices.
fn sell_amount(buy_amount: eth::U256, prices: ClearingPrices) -> Result<eth::U256, Error> {
    buy_amount
        .checked_mul(prices.buy)
        .ok_or(Error::Overflow)?
        .checked_div(prices.sell)
        .ok_or(Error::Overflow)
}

/// The amount of buy tokens received when selling the given amount of sell
/// tokens at the given clearing prices.
fn buy_amount(sell_amount: eth::U256, prices: ClearingPrices) -> Result<eth::U256, Error> {
    sell_amount
        .checked_mul(prices.sell)
        .ok_or(Error::Overflow)?
        .checked_div(prices.buy)
        .ok_or(Error::Overflow)
}

/// The price improvement of the fulfillment over the order's limit price.
///
/// The surplus is denominated in the buy token for sell orders and in the
/// sell token for buy orders, i.e. in the token which the user receives more
/// of or spends less of compared to the limit price.
fn surplus_buy_amount(
    order: &order::Order,
    executed: order::TargetAmount,
    prices: ClearingPrices,
) -> eth::U256 {
    match order.side {
        order::Side::Buy => {
            // The user spends less of the sell token than the limit allows.
            let sell_amount = sell_amount(executed.0, prices).unwrap_or_default();
            order
                .sell
                .amount
                .0
                .saturating_sub(sell_amount)
        }
        order::Side::Sell => {
            // The user receives more of the buy token than the limit allows.
            let buy_amount = buy_amount(executed.0, prices).unwrap_or_default();
            buy_amount.saturating_sub(order.buy.amount.0)
        }
    }
}

