    /// A fulfillment which buys/sells exactly the order's target amount
    /// without any solver fee.
    fn fulfillment(order: Order) -> super::Fulfillment {
        super::Fulfillment {
            order,
            executed: order.target(),
            fee: super::super::trade::Fee::Dynamic(Default::default()),
        }
    }

    /// An order which sells or buys `amount` tokens in exchange for
    /// `other_amount` tokens.
    fn order(amount: u128, other_amount: u128, side: order::Side) -> Order {
        let token = |id: u64| eth::TokenAddress::from(eth::ContractAddress(H160::from_low_u64_be(id)));
        Order {
            uid: Default::default(),
            receiver: None,
            valid_to: 100.into(),
            buy: eth::Asset {
                amount: other_amount.into(),
                token: token(0xbb),
            },
            sell: eth::Asset {
                amount: amount.into(),
                token: token(0xaa),
            },
            side,
            fee: Default::default(),
            kind: order::Kind::Limit,
            app_data: Default::default(),
            partial: Partial::No,
            pre_interactions: Default::default(),
            post_interactions: Default::default(),
            sell_token_balance: order::SellTokenBalance::Erc20,
            buy_token_balance: order::BuyTokenBalance::Erc20,
            signature: Signature {
                scheme: order::signature::Scheme::PreSign,
                data: Bytes::default(),
                signer: Default::default(),
            },
            fee_policies: vec![order::FeePolicy::PriceImprovement {
                factor: 0.5,
                max_volume_factor: 0.06,
            }],
        }
    }
}

