/// Incorporate the protocol fee into all user trades (market and limit
    /// orders), leaving liquidity orders and JIT trades unchanged.
    pub fn with_protocol_fees(mut self) -> Result<Self, SolutionError> {
        let mut trades = Vec::with_capacity(self.trades.len());
        for trade in self.trades {
            let trade = match trade {
                Trade::Fulfillment(fulfillment) => {
                    let order = fulfillment.order();

                    // The protocol fee is only applied to orders placed by end
                    // users. Liquidity orders are provided by privileged users
                    // and are not subject to the protocol fee.
                    if order.is_liquidity() {
                        Trade::Fulfillment(fulfillment)
                    } else {
                        let prices = ClearingPrices {
                            sell: self
                                .clearing_price(order.sell.token)
                                .ok_or(SolutionError::InvalidClearingPrices)?,
                            buy: self
                                .clearing_price(order.buy.token)
                                .ok_or(SolutionError::InvalidClearingPrices)?,
                        };
                        fulfillment.with_protocol_fee(prices).map_err(SolutionError::from)?
                    }
                }
                trade => trade,
            };
            trades.push(trade);
        }
        self.trades = trades;
        Ok(self)
    }

    /// The ID of this solution.
    pub fn id(&self) -> Id {
        self.id
    }

