/// An order which sells 10 `token_a` for at least 5 WETH. With a fee factor
/// of 0.5, the protocol charges half of the achieved price improvement.
async fn price_improvement_sell(web3: Web3) {
    let mut onchain = OnchainComponents::deploy(web3.clone()).await;

    let [solver] = onchain.make_solvers(to_wei(1)).await;
    let [trader] = onchain.make_accounts(to_wei(1)).await;
    let [token_a] = onchain
        .deploy_tokens_with_weth_uni_v2_pools(to_wei(1_000), to_wei(1_000))
        .await;
    let token_b = onchain.contracts().weth;

    // Fund the trader account with tokens.
    token_a.mint(trader.address(), to_wei(10)).await;

    // Approve GPv2 for trading.
    tx!(
        trader.account(),
        token_a.approve(onchain.contracts().allowance, to_wei(10))
    );

    // Start the protocol with a price improvement fee policy.
    let services = Services::new(onchain.contracts()).await;
    start_protocol(
        &services,
        solver,
        &onchain,
        "priceImprovement:0.5:1.0",
        false,
    )
    .await;

    // The order is a limit order and in the money, generating surplus.
    let order = order(&token_a, token_b.address(), trader, &onchain, OrderKind::Sell);
    let order_id = services.create_order(&order).await.unwrap();

    drive(&services).await;

    let trade = services.get_trades(&order_id).await.unwrap().pop().unwrap();
    let fee = &trade.sell_amount - &trade.sell_amount_before_fees;
    // The price improvement fee of 0.5 * surplus is charged as a protocol fee.
    assert!(
        fee >= u256_to_big_uint(&to_wei(2)) && fee <= u256_to_big_uint(&to_wei(3)),
        "unexpected fee {fee}"
    );
    // The user still receives at least their limit amount.
    assert!(trade.buy_amount >= u256_to_big_uint(&to_wei(5)));
}

