/// Start the solver, driver, autopilot and API with the given fee policy.
async fn start_protocol(
    services: &Services<'_>,
    solver: TestAccount,
    onchain: &OnchainComponents,
    fee_policy_kind: &str,
    skip_market_orders: bool,
) {
    let solver_endpoint =
        colocation::start_baseline_solver(onchain.contracts().weth.address()).await;
    colocation::start_driver(
        onchain.contracts(),
        vec![colocation::SolverEngine {
            name: "test_solver".into(),
            account: solver,
            endpoint: solver_endpoint,
        }],
    );
    services.start_autopilot(vec![
        "--drivers=test_solver|http://localhost:11088/test_solver".to_string(),
        format!("--fee-policy-kind={fee_policy_kind}"),
        format!("--fee-policy-skip-market-orders={skip_market_orders}"),
    ]);
    services
        .start_api(vec![
            "--price-estimation-drivers=test_solver|http://localhost:11088/test_solver"
                .to_string(),
        ])
        .await;
}

/// A limit order which sells 10 `token_a` for at least 5 WETH, or buys 5 WETH
/// for at most 10 `token_a`.
fn order(
    token_a: &MintableToken,
    weth: ethcontract::H160,
    trader: TestAccount,
    onchain: &OnchainComponents,
    kind: OrderKind,
) -> OrderCreation {
    OrderCreation {
        sell_token: token_a.address(),
        sell_amount: to_wei(10),
        buy_token: weth,
        buy_amount: to_wei(5),
        valid_to: model::time::now_in_epoch_seconds() + 300,
        kind,
        ..Default::default()
    }
    .sign(
        EcdsaSigningScheme::Eip712,
        &onchain.contracts().domain_separator,
        SecretKeyRef::from(&SecretKey::from_slice(trader.private_key()).unwrap()),
    )
}

/// Wait for the order to be solved and settled.
async fn drive(services: &Services<'_>) {
    wait_for_condition(TIMEOUT, || async { services.solvable_orders().await == 1 })
        .await
        .unwrap();
    wait_for_condition(TIMEOUT, || async { services.solvable_orders().await == 0 })
        .await
        .unwrap();
}

